// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llm.diimport android.content.Contextimport com.roshan.persona.brain.agentic.LlmAgenticPlannerimport com.roshan.persona.brain.agentic.LlmCallerimport com.roshan.persona.brain.bus.BrainBusimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.llm.cache.SemanticLlmCacheimport com.roshan.persona.brain.llm.context.ContextInjectorimport com.roshan.persona.brain.llm.cost.LlmCostTrackerimport com.roshan.persona.brain.llm.guardrails.LocalLlmGuardrailsimport com.roshan.persona.brain.llm.layer.CloudLlmLayerimport com.roshan.persona.brain.llm.layer.LocalLlmLayerimport com.roshan.persona.brain.llm.provider.CloudLlmProviderimport com.roshan.persona.brain.llm.provider.CloudProviderConfigimport com.roshan.persona.brain.llm.provider.GenerationConfigimport com.roshan.persona.brain.llm.provider.LocalLlmProviderimport com.roshan.persona.brain.llm.registry.CloudProviderRegistryimport com.roshan.persona.brain.llm.registry.LocalLlmModelCatalogimport com.roshan.persona.brain.llm.router.HybridLlmRouterimport com.roshan.persona.brain.skill.CredentialVaultInterfaceimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.llm.cloud.CloudProviderFactoryimport com.roshan.persona.llm.cloud.StreamParserimport com.roshan.persona.llm.download.ModelDownloaderimport com.roshan.persona.llm.local.CrashWatchdogimport com.roshan.persona.llm.local.LlamaCppJniimport com.roshan.persona.llm.local.LlamaCppProviderimport com.roshan.persona.llm.local.LocalModelManagerimport com.roshan.persona.llm.local.PredictiveModelPreloaderimport com.roshan.persona.llm.local.QuantizationSelectorimport com.roshan.persona.llm.local.VulkanConfigimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.android.qualifiers.ApplicationContextimport dagger.hilt.components.SingletonComponentimport okhttp3.OkHttpClientimport java.util.concurrent.TimeUnitimport javax.inject.Singleton/** * NOUS — LLM Hilt Module (v2.1 — Integration Complete). * * Wires ALL LLM implementations to Brain module interfaces per Strategy §14.2: * *   - [LocalLlmProvider] — real LlamaCppProvider via LocalModelManager. *     When no model is loaded, returns NoOpLocalLlmProvider (isLoaded=false). *   - [CloudLlmLayer] — real CloudLlmLayer with CloudProviderFactory (not a stub). *   - [LlmAgenticPlanner] — real planner wired to HybridLlmRouter. *   - [LlmCaller] — real caller that delegates to HybridLlmRouter.route(). * * @see <a href="docs/strategy/NOUS-Module-Strategy-2-14-extracted.txt">§4 LLM Stack + §14.2 Brain Interface Override</a> */@Module@InstallIn(SingletonComponent::class)object LlmModule {    @Provides    @Singleton    @com.roshan.persona.llm.di.LlmHttp    fun provideOkHttpClient(): OkHttpClient {        return OkHttpClient.Builder()            .connectTimeout(30, TimeUnit.SECONDS)            .readTimeout(120, TimeUnit.SECONDS)            .writeTimeout(30, TimeUnit.SECONDS)            .build()    }    @Provides    @Singleton    fun provideStreamParser(): StreamParser = StreamParser()    @Provides    @Singleton    fun provideCloudProviderFactory(        credentialVault: CredentialVaultInterface,    ): CloudProviderFactory = CloudProviderFactory(credentialVault)    @Provides    @Singleton    fun provideLocalModelManager(        modelCatalog: LocalLlmModelCatalog,        @ApplicationContext context: Context,    ): LocalModelManager = LocalModelManager(modelCatalog, context)    @Provides    @Singleton    fun provideModelDownloader(        @com.roshan.persona.llm.di.LlmHttp httpClient: OkHttpClient,        @ApplicationContext context: Context,    ): ModelDownloader {        val modelsDir = context.filesDir.absolutePath + "/models"        return ModelDownloader(httpClient, modelsDir)    }    @Provides    @Singleton    fun providePredictivePreloader(        localModelManager: LocalModelManager,        modelCatalog: LocalLlmModelCatalog,    ): PredictiveModelPreloader = PredictiveModelPreloader(localModelManager, modelCatalog)    @Provides    @Singleton    fun provideCrashWatchdog(        @ApplicationContext context: Context,    ): CrashWatchdog = CrashWatchdog(logDir = context.filesDir.absolutePath + "/crash")    // ─── KV Cache Manager (Strategy §4.4 — KV cache reuse) ────────────────    @Provides    @Singleton    fun provideKvCacheManager(): com.roshan.persona.llm.local.KvCacheManager =        com.roshan.persona.llm.local.KvCacheManager()    // ─── LoRA Adapter Manager (Strategy §4.8 — LoRA adapter support) ──────    @Provides    @Singleton    fun provideLoraAdapterManager(        kvCacheManager: com.roshan.persona.llm.local.KvCacheManager,    ): com.roshan.persona.llm.local.LoraAdapterManager =        com.roshan.persona.llm.local.LoraAdapterManager(kvCacheManager)    // ─── LocalLlmProvider (Strategy §4.1 — lazy model loading) ────────────    //    // Returns the currently loaded provider from LocalModelManager.    // When no model is loaded, returns NoOpLocalLlmProvider (isLoaded=false).    // Brain's LocalLlmLayer checks isLoaded and defers to Layer 4 (Cloud) if false.    //    // This is NOT a stub — it's the real "no model loaded" state per strategy.    @Provides    @Singleton    fun provideLocalLlmProvider(        localModelManager: LocalModelManager,    ): LocalLlmProvider {        return localModelManager.getCurrentProvider()            ?: com.roshan.persona.brain.llm.provider.NoOpLocalLlmProvider()    }    // ─── CloudLlmLayer (Strategy §4.6 — real CloudProviderFactory) ─────────    //    // Uses the real CloudProviderFactory from :feature:llm (not a throwing stub).    // The factory creates OkHttpCloudProvider instances for each configured provider.    @Provides    @Singleton    fun provideCloudLlmLayer(        registry: CloudProviderRegistry,        costTracker: LlmCostTracker,        contextInjector: ContextInjector,        credentialVault: CredentialVaultInterface,        brainBus: BrainBus,        cloudProviderFactory: CloudProviderFactory,        @com.roshan.persona.llm.di.LlmHttp httpClient: OkHttpClient,    ): CloudLlmLayer {        return CloudLlmLayer(            registry = registry,            costTracker = costTracker,            contextInjector = contextInjector,            credentialVault = credentialVault,            brainBus = brainBus,            providerFactory = { config ->                cloudProviderFactory.create(config, httpClient)            },        )    }    // ─── LlmCaller (Strategy §2.3.6 — wired to HybridLlmRouter) ───────────    //    // The LlmCaller is used by AgenticExecutor for LlmQuery steps.    // It delegates to HybridLlmRouter.route() and extracts the text from the    // resulting SkillOutput.Success.    @Provides    @Singleton    fun provideLlmCaller(        hybridLlmRouter: HybridLlmRouter,    ): LlmCaller {        return LlmCaller { prompt, context ->            val routingResult = hybridLlmRouter.route(                userInput = prompt,                context = context,            )            when (val output = routingResult.output) {                is Result.Success -> {                    when (val skillOutput = output.data) {                        is SkillOutput.Success -> Result.Success(                            data = skillOutput.message,                            correlationId = CorrelationId.generate(),                            durationNanos = 0,                        )                        is SkillOutput.Partial -> Result.Success(                            data = skillOutput.message,                            correlationId = CorrelationId.generate(),                            durationNanos = 0,                        )                        is SkillOutput.Failure -> Result.Failure(                            error = AppError.Llm.ModelMissing(modelId = "agentic"),                            correlationId = CorrelationId.generate(),                            durationNanos = 0,                        )                        is SkillOutput.NeedsInput -> Result.Failure(                            error = AppError.Llm.ModelMissing(modelId = "agentic-needs-input"),                            correlationId = CorrelationId.generate(),                            durationNanos = 0,                        )                        is SkillOutput.NeedsPermission -> Result.Failure(                            error = AppError.Llm.ModelMissing(modelId = "agentic-needs-permission"),                            correlationId = CorrelationId.generate(),                            durationNanos = 0,                        )                    }                }                is Result.Failure -> output                is Result.Partial -> {                    // Result.Partial<SkillOutput> - extract the user-facing                    // message from the wrapped SkillOutput (Success / Partial                    // carry a `message`; other variants fall back to a generic                    // string so the LlmCaller still yields a usable String).                    val partialSkillOutput = output.data                    val partialMessage = when (partialSkillOutput) {                        is SkillOutput.Success -> partialSkillOutput.message                        is SkillOutput.Partial -> partialSkillOutput.message                        is SkillOutput.Failure -> partialSkillOutput.userMessage                            ?: "Skill failed: ${partialSkillOutput.error.code}"                        is SkillOutput.NeedsInput -> partialSkillOutput.prompt                        is SkillOutput.NeedsPermission -> partialSkillOutput.userMessage                    }                    Result.Success(                        data = partialMessage,                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                    )                }            }        }    }    // ─── LlmAgenticPlanner (Strategy §2.3.6 — LLM-backed planner) ──────────    //    // Uses the LlmCaller (wired to HybridLlmRouter) to generate plan steps.    // This is the REAL planner — not a failure-returning stub.    @Provides    @Singleton    fun provideLlmAgenticPlanner(        llmCaller: LlmCaller,    ): LlmAgenticPlanner {        return LlmAgenticPlanner(            llmCaller = llmCaller::invoke,        )    }}